css:
.content-wrapper .content {
  background-color: hsl(213, 19%, 18%);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: hsl(0, 0%, 100%);
  width: 20rem;
  height: 20rem;
  padding: 20px;
  border-radius: 30px;
}

.rating-star {
  width: 40px;
  height: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: hsl(217, 12%, 63%, 0.4);
  border-radius: 50%;
}
.rating-star img {
  width: 15px;
}

.title {
  font-size: 20px;
  font-weight: 700;
}
.text {
  font-size: 15px;
  font-weight: 400;
  line-height: 1.3;
  color: hsl(217, 12%, 63%);
}
.rating {
  display: flex;
  justify-content: space-between;
}
.rating label {
  cursor: pointer;
  width: 40px;
  height: 40px;
  background-color: hsla(217, 12%, 63%, 0.4);
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 400;
}
.rating label:hover {
  color: hsl(213, 19%, 18%);
  background-color: hsl(0, 0%, 100%);
}

.rating input[type="radio"] {
  display: none;
}

.rating input[type="radio"]:checked + label {
  background-color: hsl(25, 97%, 53%);
  color: var(--Dark-Blue);
  font-weight: 400;
}
.button {
  background-color: hsl(25, 97%, 53%);
  color: hsl(213, 19%, 18%);
  font-weight: 700;
  text-transform: uppercase;
  width: 100%;
  padding: 10px;
  border-radius: 30px;
  border: none;
}

.button:hover {
  background-color: hsl(0, 0%, 100%);
}

.center {
  display: flex;
  align-items: center;
  text-align: center;
}

.select {
  color: hsl(25, 97%, 53%);
  background: hsl(217, 12%, 63%);
  border-radius: 30px;
  padding: 4px 20px;
}
